import pytest

from your_module import is_palindrome


@pytest.mark.parametrize(
    "value",
    [
        "racecar",
        "RaceCar",
        "A Santa at NASA",
        "never odd or even",
        "Was it a car or a cat I saw",
    ],
)
def test_is_palindrome_happy_path(value):
    assert is_palindrome(value) is True


@pytest.mark.parametrize(
    "value",
    [
        "hello",
        "palindrome",
        "Race a car",
        "not a palindrome",
    ],
)
def test_is_palindrome_returns_false_for_non_palindromes(value):
    assert is_palindrome(value) is False


@pytest.mark.parametrize(
    "value",
    [
        "",
        " ",
        "     ",
        "a",
        "A",
    ],
)
def test_is_palindrome_edge_cases(value):
    assert is_palindrome(value) is True


def test_is_palindrome_ignores_spaces_and_case_only():
    assert is_palindrome("Taco Cat") is True


def test_is_palindrome_does_not_ignore_punctuation():
    assert is_palindrome("A man, a plan, a canal, Panama") is False


def test_is_palindrome_does_not_ignore_tabs_or_newlines():
    assert is_palindrome("a\tb\ta") is True
    assert is_palindrome("a\nb\na") is True
    assert is_palindrome("ab\t a") is False


@pytest.mark.parametrize(
    "value",
    [
        None,
        12321,
        ["r", "a", "c", "e", "c", "a", "r"],
    ],
)
def test_is_palindrome_raises_for_non_string_inputs(value):
    with pytest.raises(AttributeError):
        is_palindrome(value)
